result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/ocean.js", "content": "import * as THREE from 'three';

/**
 * Sum-of-sines ocean surface height at world position (x, z) and time t.
 */
export function heightAt(x, z, t) {
  return (
    0.6 * Math.sin(0.8 * x + 1.4 * t) +
    0.3 * Math.sin(1.7 * z - 0.9 * t) +
    0.15 * Math.sin(1.1 * (x + z) + 2.3 * t)
  );
}

/**
 * Create a flat-lying plane mesh for the animated ocean surface.
 * The original (pre-animation) xz coordinates of every vertex are stored
 * in mesh.userData.basePositions so updateOcean can recompute heights.
 */
export function createOcean({ size = 40, segments = 64 } = {}) {
  const geometry = new THREE.PlaneGeometry(size, size, segments, segments);
  geometry.rotateX(-Math.PI / 2);

  const positions = geometry.attributes.position;
  const basePositions = new Float32Array(positions.array.length);
  basePositions.set(positions.array);

  const material = new THREE.MeshStandardMaterial({
    color: 0x1a5f7a,
    roughness: 0.35,
    metalness: 0.1,
    transparent: true,
    opacity: 0.92,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.userData.basePositions = basePositions;

  // Initialize vertex heights so the mesh is valid even before the first update.
  updateOcean(mesh, 0);

  return mesh;
}

/**
 * Displace every vertex to its wave height for time t.
 * Marks the position attribute needsUpdate so changes reach the GPU.
 */
export function updateOcean(mesh, t) {
  const positions = mesh.geometry.attributes.position;
  const base = mesh.userData.basePositions;
  const array = positions.array;

  for (let i = 0; i < array.length; i += 3) {
    array[i + 1] = heightAt(base[i], base[i + 2], t);
  }

  positions.needsUpdate = true;
}
"})
