result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/ocean.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { createOcean, heightAt, updateOcean } from '../src/ocean.js';

describe('ocean surface', () => {
  const mesh = createOcean({ size: 40, segments: 64 });
  const positions = mesh.geometry.attributes.position;
  const base = mesh.userData.basePositions;

  it('is a plane rotated flat, with original xz kept in userData', () => {
    expect(mesh).toBeInstanceOf(THREE.Mesh);
    // After rotateX(-PI/2), every vertex lies in the xz-plane (y === 0 pre-update).
    for (let i = 0; i < base.length; i += 3) {
      expect(base[i + 1]).toBe(0);
    }
    expect(mesh.geometry.attributes.position).toBe(positions);
  });

  it('updateOcean(m, 2.5): five sampled vertices match heightAt exactly', () => {
    updateOcean(mesh, 2.5);

    const count = positions.count;
    const samples = [0, Math.floor(count / 4), Math.floor(count / 2), Math.floor((3 * count) / 4), count - 1];

    for (const vi of samples) {
      const x = base[vi * 3];
      const z = base[vi * 3 + 2];
      expect(positions.getY(vi)).toBeCloseTo(heightAt(x, z, 2.5), 9);
    }
  });

  it('every vertex y is within [-1.05, 1.05]', () => {
    for (let i = 0; i < positions.count; i++) {
      const y = positions.getY(i);
      expect(y).toBeGreaterThanOrEqual(-1.05);
      expect(y).toBeLessThanOrEqual(1.05);
    }
  });

  it('updateOcean is idempotent for the same t (buffers byte-equal)', () => {
    updateOcean(mesh, 2.5);
    const before = Buffer.from(positions.array.buffer.slice(0));

    updateOcean(mesh, 2.5);
    const after = Buffer.from(positions.array.buffer.slice(0));

    expect(Buffer.compare(before, after)).toBe(0);
  });

  it('mean height over all vertices at t=0 is below 0.2 in absolute value', () => {
    updateOcean(mesh, 0);
    let sum = 0;
    for (let i = 0; i < positions.count; i++) sum += positions.getY(i);
    const mean = sum / positions.count;
    expect(Math.abs(mean)).toBeLessThan(0.2);
  });

  it('marks the position attribute needsUpdate', () => {
    positions.needsUpdate = false;
    updateOcean(mesh, 1.0);
    expect(positions.needsUpdate).toBe(true);
  });
});
"})
